/**
 * Configures schema-driven SQLite migration generation for the application.
 * Drizzle Kit has no configuration initializer; migrations and snapshots are
 * generated by its CLI. Runtime database location is owned by the application.
 */
import { defineConfig } from "drizzle-kit";

export default defineConfig({
  dialect: "sqlite",
  schema: ["./src/storage/sqlite/schema.ts", "./src/storage/sqlite/auth-schema.ts"],
  out: "./drizzle",
});
